@SpringBootTest(webEnvironment=SpringBootTest.WebEnvironment.RANDOM_PORT,properties={"spring.datasource.url=jdbc:h2:mem:verification;MODE=MySQL;DB_CLOSE_DELAY=-1","spring.datasource.username=sa","spring.datasource.password=","spring.jpa.hibernate.ddl-auto=validate","ping.public-base-url=http://127.0.0.1:8090"}) @ActiveProfiles("verification-test")
class VerificationTests {
 @Autowired EventService events;@Autowired EncounterService config;@Autowired ParticipantService people;@Autowired MatchingService matching;@Autowired MatchService matches;@Autowired MatchRepository records;@Autowired CredentialService credentials;@Autowired RewardService rewards;@Autowired BenefitAdminService benefits;@Autowired AccountService accounts;@Autowired InterestService interests;@Autowired JdbcTemplate sql;@Autowired PasswordEncoder encoder;@LocalServerPort int port;
 long event,a,b,match,accountA,accountB;static final String PASSWORD="Contraseña exclusiva de fixture2026";
 @BeforeEach void setup(){var f=new EventForm();f.setName("Verificación ficticia "+UUID.randomUUID());f.setDeliveryName("Mesa original");f.setDeliveryDirections("Vestíbulo de prueba");event=events.create(f).getId();events.transition(event,EventStatus.OPEN);var p=new PointForm();p.setName("Patio público");p.setDirections("Junto al letrero");long point=config.savePoint(event,null,p);var activity=new ActivityForm();activity.setTitle("Una recomendación");activity.setInstructions("Compartan una recomendación.");activity.setRewardPoints(37);activity.setPointIds(Set.of(point));config.saveActivity(event,null,activity);accountA=account();accountB=account();a=person(accountA,event,"Persona A");b=person(accountB,event,"Persona B");match=matching.search(a);matches.accept(match,a);matches.accept(match,b);}
 @AfterEach void clear(){SecurityContextHolder.clearContext();}
 long account(){String email=UUID.randomUUID()+"@fixture.test";sql.update("insert into ping_accounts(email,password_hash,email_verified) values(?,?,true)",email,encoder.encode(PASSWORD));return accounts.find(email).orElseThrow();}
 long person(long account,long event,String name){var f=new ParticipantForm();f.setAlias(name);f.setEventId(event);f.setAvailable(true);long id=people.create(f).id();accounts.bind(account,id,event);return id;}
 String key(){return UUID.randomUUID().toString();}
 String ip(){return "fixture-"+event;}
 void arrived(){matches.arrive(match,a);matches.arrive(match,b);}
 CredentialService.Issued issue(long self){return credentials.encounter(match,self,key());}
 void cross(){arrived();var ca=issue(a);var cb=issue(b);credentials.verify(match,a,cb.manual(),ip());credentials.verify(match,b,"PING:ENCOUNTER:"+ca.token(),ip());}
 void complete(){cross();matches.confirm(match,a);matches.confirm(match,b);}
 long benefit(){var f=new BenefitForm();f.setName("Beneficio ficticio");f.setDefaultDelivery(true);f.setPointsCost(20);return benefits.save(event,null,f);}
 long general(){String email="general@fixture.test";if(accounts.find(email).isEmpty())accounts.bootstrap(email,PASSWORD);return accounts.find(email).orElseThrow();}
 void as(long id){var user=accounts.user(id);SecurityContextHolder.getContext().setAuthentication(UsernamePasswordAuthenticationToken.authenticated(user,null,user.getAuthorities()));}
 void login(TestBrowser browser,long account)throws Exception{browser.get("/login");assertThat(browser.post("/login",Map.of("email",accounts.user(account).email(),"password",PASSWORD)).statusCode()).isEqualTo(302);}
 @Test void bothRealArrivalsAndVerificationsAreRequiredBeforeAnyCredit(){assertThat(matches.get(match,a).verificationPolicy()).isEqualTo(2);assertThatThrownBy(()->matches.confirm(match,a)).isInstanceOf(BusinessRuleException.class);assertThatThrownBy(()->issue(a)).isInstanceOf(BusinessRuleException.class);matches.arrive(match,a);assertThatThrownBy(()->matches.confirm(match,a)).isInstanceOf(BusinessRuleException.class);matches.arrive(match,b);assertThatThrownBy(()->matches.confirm(match,a)).isInstanceOf(BusinessRuleException.class);var ca=issue(a);credentials.verify(match,b,ca.manual(),ip());assertThatThrownBy(()->matches.confirm(match,b)).isInstanceOf(BusinessRuleException.class);var cb=issue(b);credentials.verify(match,a,cb.manual(),ip());matches.confirm(match,a);assertThat(people.get(a).points()).isZero();matches.confirm(match,b);matches.confirm(match,b);assertThat(people.get(a).points()).isEqualTo(37);assertThat(people.get(b).points()).isEqualTo(37);}
 @Test void ownSharedWrongPurposeForeignMatchAndOutsiderCodesAreRejected(){arrived();var ca=issue(a);assertThatThrownBy(()->credentials.verify(match,a,ca.manual(),ip())).isInstanceOf(BusinessRuleException.class);assertThatThrownBy(()->credentials.verify(match,b,matches.get(match,b).word(),ip())).isInstanceOf(BusinessRuleException.class);assertThatThrownBy(()->credentials.verify(match,b,"PING:REDEMPTION:"+ca.token(),ip())).isInstanceOf(BusinessRuleException.class);long c=person(account(),event,"Persona C"),d=person(account(),event,"Persona D");long foreign=matching.search(c);matches.accept(foreign,c);matches.accept(foreign,d);matches.arrive(foreign,c);matches.arrive(foreign,d);var cc=credentials.encounter(foreign,c,key());assertThatThrownBy(()->credentials.verify(match,b,cc.manual(),ip())).isInstanceOf(BusinessRuleException.class);assertThatThrownBy(()->credentials.verify(match,c,ca.manual(),ip())).isInstanceOf(BusinessRuleException.class);}
 @Test void renewalInvalidatesOnlyPendingCodeAndVerifiedReceiptDoesNotExpire(){arrived();var ca=issue(a);var cb=issue(b);credentials.verify(match,a,cb.manual(),ip());var renewed=issue(a);assertThatThrownBy(()->credentials.verify(match,b,ca.manual(),ip())).isInstanceOf(BusinessRuleException.class);credentials.verify(match,b,renewed.manual(),ip());sql.update("update purpose_credentials set expires_at=? where context_id=?",java.sql.Timestamp.from(java.time.Instant.now().minusSeconds(60)),match);credentials.verify(match,a,cb.manual(),ip());matches.confirm(match,a);matches.confirm(match,b);assertThat(people.get(a).points()).isEqualTo(37);}
 @Test void expiredPendingCodeAndCancellationCannotVerify(){arrived();var ca=issue(a);sql.update("update purpose_credentials set expires_at=? where id=?",java.sql.Timestamp.from(java.time.Instant.now().minusSeconds(60)),ca.id());assertThatThrownBy(()->credentials.verify(match,b,ca.manual(),ip())).isInstanceOf(BusinessRuleException.class);var current=issue(a);matches.cancel(match,b);assertThatThrownBy(()->credentials.verify(match,b,current.manual(),ip())).isInstanceOf(BusinessRuleException.class);assertThat(sql.queryForObject("select revoked from purpose_credentials where id=?",Boolean.class,current.id())).isTrue();}
 @Test void successfulPairDoesNotRepeatInEitherOrderOrNewAvailabilityCycle(){complete();assertThatThrownBy(()->matching.search(a)).isInstanceOf(BusinessRuleException.class);assertThatThrownBy(()->matching.search(b)).isInstanceOf(BusinessRuleException.class);var f=new AvailabilityForm();f.setAvailable(false);f.setVersion(people.get(a).version());people.setAvailability(a,f);f.setAvailable(true);f.setVersion(people.get(a).version());people.setAvailability(a,f);assertThatThrownBy(()->matching.search(a)).isInstanceOf(BusinessRuleException.class);assertThat(records.successfulPartners(event,b)).contains(a);var other=new EventForm();other.setName("Otro evento ficticio");long e=events.create(other).getId();events.transition(e,EventStatus.OPEN);long x=person(accountA,e,"Persona A"),y=person(accountB,e,"Persona B");assertThat(matching.search(x)).isPositive();}
 @Test void paidReceiptFreezesDeliveryAndRenewalNeverDebitsAgain(){complete();long benefit=benefit();String request=key();long claim=rewards.request(a,benefit,request);var code=credentials.redemption(claim,a,key());sql.update("update purpose_credentials set expires_at=? where id=?",java.sql.Timestamp.from(java.time.Instant.now().minusSeconds(60)),code.id());as(general());assertThatThrownBy(()->credentials.lookup(code.manual(),ip())).isInstanceOf(BusinessRuleException.class);assertThat(rewards.request(a,benefit,request)).isEqualTo(claim);var changed=EventForm.from(events.get(event));changed.setDeliveryName("Lugar nuevo");events.update(event,changed);var renewed=credentials.redemption(claim,a,key());assertThat(credentials.valid(code)).isFalse();assertThat(credentials.valid(renewed)).isTrue();assertThat(credentials.personal(claim,a).claimLocation()).isEqualTo("Mesa original");assertThat(people.get(a).points()).isEqualTo(17);}
 @Test void onlyAuthorizedOtherAccountCanDeliverAndReplayIsIdempotent(){complete();long benefit=benefit(),claim=rewards.request(a,benefit,key());var code=credentials.redemption(claim,a,key());accounts.assign(general(),accountA,event,true);as(accountA);assertThatThrownBy(()->credentials.deliver(code.manual(),ClaimStatus.DELIVERED,ip())).isInstanceOf(org.springframework.security.access.AccessDeniedException.class);long foreignAdmin=account();var other=new EventForm();other.setName("Evento ajeno");long e=events.create(other).getId();accounts.assign(general(),foreignAdmin,e,true);as(foreignAdmin);assertThatThrownBy(()->credentials.lookup(code.manual(),ip())).isInstanceOf(org.springframework.security.access.AccessDeniedException.class);as(general());assertThat(credentials.lookup(code.manual(),ip()).status()).isEqualTo("REQUESTED");assertThat(credentials.deliver(code.manual(),ClaimStatus.DELIVERED,ip())).isEqualTo(claim);assertThat(credentials.deliver(code.manual(),ClaimStatus.DELIVERED,ip())).isEqualTo(claim);assertThat(people.get(a).points()).isEqualTo(17);assertThat(credentials.personal(claim,a).status()).isEqualTo(ClaimStatus.DELIVERED);assertThatThrownBy(()->credentials.deliver(code.manual(),ClaimStatus.INCIDENT,ip())).isInstanceOf(BusinessRuleException.class);}
 @Test void legacyFinishCannotBypassReceiptCodeAndWrongPurposeCannotDeliver(){complete();long benefit=benefit(),claim=rewards.request(a,benefit,key());as(general());assertThatThrownBy(()->rewards.finish(claim,ClaimStatus.DELIVERED)).isInstanceOf(BusinessRuleException.class);assertThatThrownBy(()->credentials.lookup("PING:ENCOUNTER:"+AccountService.secret(),ip())).isInstanceOf(BusinessRuleException.class);assertThat(credentials.personal(claim,a).status()).isEqualTo(ClaimStatus.REQUESTED);}
 @Test void twoStaffDevicesCannotRecordDifferentResultsForOneReceipt()throws Exception{complete();long benefit=benefit(),claim=rewards.request(a,benefit,key());var code=credentials.redemption(claim,a,key());long general=general();var gate=new CountDownLatch(1);try(var pool=Executors.newFixedThreadPool(2)){var one=pool.submit(()->{as(general);gate.await();try{credentials.deliver(code.manual(),ClaimStatus.DELIVERED,ip());return true;}catch(BusinessRuleException ex){return false;}finally{SecurityContextHolder.clearContext();}});var two=pool.submit(()->{as(general);gate.await();try{credentials.deliver(code.manual(),ClaimStatus.INCIDENT,ip());return true;}catch(BusinessRuleException ex){return false;}finally{SecurityContextHolder.clearContext();}});gate.countDown();assertThat(one.get(15,TimeUnit.SECONDS)^two.get(15,TimeUnit.SECONDS)).isTrue();}assertThat(people.get(a).points()).isEqualTo(17);}
 // Auditoría D01–D14 · A01/A03: recorrido HTTP del encargado tras renovar el código; la entrega persiste una sola vez y el recibo cierra su seguimiento.
 @Test void renewedReceiptCodeIsDeliveredOverHttpAndReceiptShowsClosedTracking()throws Exception{complete();long benefit=benefit(),claim=rewards.request(a,benefit,key());try(var aa=new TestBrowser(port);var staff=new TestBrowser(port)){login(aa,accountA);login(staff,general());aa.get("/me/claims/"+claim);aa.post("/me/claims/"+claim+"/code",Map.of("requestKey",key()));String first=aa.get("/me/claims/"+claim).body();var keyMatch=Pattern.compile("name=\"requestKey\" value=\"([^\"]+)\"").matcher(first);assertThat(keyMatch.find()).isTrue();aa.post("/me/claims/"+claim+"/code",Map.of("requestKey",keyMatch.group(1),"renew","true"));var find=Pattern.compile("<code[^>]*data-private-credential[^>]*>([^<]+)</code>").matcher(aa.get("/me/claims/"+claim).body());assertThat(find.find()).isTrue();String code=find.group(1);staff.get("/organizer/redemptions");assertThat(staff.post("/organizer/redemptions/lookup",Map.of("credential",code)).body()).contains("Confirmar entrega");assertThat(staff.post("/organizer/redemptions/deliver",Map.of("credential",code,"status","DELIVERED")).statusCode()).isEqualTo(302);assertThat(staff.post("/organizer/redemptions/deliver",Map.of("credential",code,"status","DELIVERED")).statusCode()).isEqualTo(302);assertThat(credentials.personal(claim,a).status()).isEqualTo(ClaimStatus.DELIVERED);assertThat(people.get(a).points()).isEqualTo(17);assertThat(sql.queryForObject("select count(*) from auth_audit where action='DELIVER_CLAIM' and subject_id=?",Integer.class,claim)).isEqualTo(1);String receipt=aa.get("/me/claims/"+claim).body();assertThat(receipt).contains("Entregado").doesNotContain("Por entregar","Acércate al punto de entrega","data-private-credential");}}
 // DEC-058 · D12: la lista de conexiones anteriores solo dice «Verificado» cuando constan las dos verificaciones personales.
 @Test void historyMarksVerifiedOnlyWithBothRealVerifications()throws Exception{complete();try(var aa=new TestBrowser(port)){login(aa,accountA);String body=aa.get("/me/connections").body();assertThat(body).contains("data-verified=\"true\"",">Verificado<");}}
 @Test void historicalCompletionWithoutVerificationIsNotLabelledVerified()throws Exception{sql.update("update ping_matches set verification_policy=1,first_confirmed=true where id=?",match);matches.confirm(match,b);assertThat(matches.get(match,a).status()).isEqualTo(MatchStatus.COMPLETED);try(var aa=new TestBrowser(port)){login(aa,accountA);String body=aa.get("/me/connections").body();assertThat(body).contains("data-status=\"COMPLETED\"","data-verified=\"false\"").doesNotContain(">Verificado<");}}
 @Test void historicalActiveKeepsOptionalPolicyAndOriginalAmount(){sql.update("update ping_matches set verification_policy=1,first_confirmed=true where id=?",match);matches.confirm(match,b);assertThat(matches.get(match,a).status()).isEqualTo(MatchStatus.COMPLETED);assertThat(people.get(a).points()).isEqualTo(37);}
 @Test void extendedCatalogDoesNotTruncateExplicitSnapshots(){matches.cancel(match,a);var e=new EventForm();e.setName("Catálogo amplio ficticio");long event=events.create(e).getId();events.transition(event,EventStatus.OPEN);long x=person(accountA,event,"Amplio A"),y=person(accountB,event,"Amplio B");var ids=interests.catalog().stream().map(Interest::getId).toList();for(long id:List.of(x,y)){var f=interests.selection(id);f.setInterestIds(ids);interests.save(id,f);}long m=matching.search(x);assertThat(matches.get(m,x).commonInterests().length()).isGreaterThan(700);assertThat(people.get(x).interests()).hasSize(264);}
 @Test void directHttpCannotSkipGatesAndEachPersonSeesOnlyOwnChallenge()throws Exception{try(var aa=new TestBrowser(port);var bb=new TestBrowser(port);var anonymous=new TestBrowser(port)){login(aa,accountA);login(bb,accountB);var first=aa.get("/matches/"+match);assertThat(first.body()).doesNotContain("id=\"am-confirm-action\"");assertThat(aa.post("/matches/"+match+"/confirm",Map.of()).statusCode()).isEqualTo(409);assertThat(anonymous.post("/matches/"+match+"/verify",Map.of("credential","X")).statusCode()).isEqualTo(403);arrived();aa.get("/matches/"+match);bb.get("/matches/"+match);aa.post("/matches/"+match+"/code",Map.of("requestKey",key()));bb.post("/matches/"+match+"/code",Map.of("requestKey",key()));String aPage=aa.get("/matches/"+match).body(),bPage=bb.get("/matches/"+match).body();var pattern=Pattern.compile("<code[^>]*data-private-credential[^>]*>([^<]+)</code>");var ma=pattern.matcher(aPage);var mb=pattern.matcher(bPage);assertThat(ma.find()).isTrue();assertThat(mb.find()).isTrue();String ca=ma.group(1),cb=mb.group(1);assertThat(aPage).doesNotContain(cb);assertThat(bPage).doesNotContain(ca);assertThat(aa.get("/me/state").body()).doesNotContain(ca,cb);var qr=aa.bytes("/matches/"+match+"/my-code.png");assertThat(qr.statusCode()).isEqualTo(200);var img=javax.imageio.ImageIO.read(new java.io.ByteArrayInputStream(qr.body()));int[] pixels=img.getRGB(0,0,img.getWidth(),img.getHeight(),null,0,img.getWidth());var bitmap=new com.google.zxing.BinaryBitmap(new com.google.zxing.common.HybridBinarizer(new com.google.zxing.RGBLuminanceSource(img.getWidth(),img.getHeight(),pixels)));String payload=new com.google.zxing.qrcode.QRCodeReader().decode(bitmap).getText();assertThat(payload).startsWith("PING:ENCOUNTER:");assertThat(bb.post("/matches/"+match+"/verify",Map.of("credential",payload)).statusCode()).isEqualTo(302);assertThat(matches.get(match,b).verified()).isTrue();assertThat(aa.post("/matches/"+match+"/verify",Map.of("credential",cb)).statusCode()).isEqualTo(302);assertThat(aa.get("/matches/"+match).body()).contains("id=\"am-confirm-action\"");}}
 @Test void verificationRateLimitExpiresWithoutLosingArrivals(){arrived();var cb=issue(b);for(int i=0;i<8;i++)assertThatThrownBy(()->credentials.verify(match,a,"INVALIDO",ip())).isInstanceOf(BusinessRuleException.class);assertThatThrownBy(()->credentials.verify(match,a,cb.manual(),ip())).isInstanceOf(BusinessRuleException.class).hasMessageContaining("Espera");assertThat(matches.get(match,a).verified()).isFalse();sql.update("update auth_throttle set expires_at=? where bucket_key=?",java.sql.Timestamp.from(java.time.Instant.now().minusSeconds(60)),AccountService.hash("verify-account:"+a+":"+match));credentials.verify(match,a,cb.manual(),ip());assertThat(matches.get(match,a).verified()).isTrue();assertThat(matches.get(match,a).arrived()).isTrue();assertThat(people.get(a).points()).isZero();}
 @Test void receiptHttpIsPrivateAndOldEndpointCannotBypassCode()throws Exception{complete();long benefit=benefit(),claim=rewards.request(a,benefit,key());try(var aa=new TestBrowser(port);var bb=new TestBrowser(port);var staff=new TestBrowser(port)){login(aa,accountA);login(bb,accountB);login(staff,general());assertThat(aa.get("/me/claims/"+claim).statusCode()).isEqualTo(200);aa.post("/me/claims/"+claim+"/code",Map.of("requestKey",key()));String own=aa.get("/me/claims/"+claim).body();var find=Pattern.compile("<code[^>]*data-private-credential[^>]*>([^<]+)</code>").matcher(own);assertThat(find.find()).isTrue();String code=find.group(1);var forbidden=bb.get("/me/claims/"+claim);assertThat(forbidden.statusCode()).isNotEqualTo(200);assertThat(forbidden.body()).doesNotContain(code);assertThat(aa.get("/organizer/redemptions").statusCode()).isEqualTo(403);staff.get("/organizer/redemptions");assertThat(staff.post("/admin/claims/"+claim,Map.of("status","DELIVERED")).statusCode()).isEqualTo(409);var preview=staff.post("/organizer/redemptions/lookup",Map.of("credential",code));assertThat(preview.statusCode()).isEqualTo(200);assertThat(preview.body()).contains("Confirmar entrega").doesNotContain(accounts.user(accountA).email(),accounts.user(accountB).email());assertThat(staff.post("/organizer/redemptions/deliver",Map.of("credential",code,"status","DELIVERED")).statusCode()).isEqualTo(302);assertThat(staff.post("/organizer/redemptions/deliver",Map.of("credential",code,"status","DELIVERED")).statusCode()).isEqualTo(302);assertThat(people.get(a).points()).isEqualTo(17);}}
}
